input.command:
node -v && node -e '
const fs=require("fs");
const data=JSON.parse(fs.readFileSync("input.json","utf8"));
if(typeof data.quantity!=="number"||typeof data.unitPrice!=="number") throw new Error("quantity/unitPrice must be numbers");
const total=data.quantity*data.unitPrice;
fs.writeFileSync("answer.json", JSON.stringify({total}, null, 2)+"\n");
console.log("computed total:", total);
'

node -e '
const fs=require("fs");
const input=JSON.parse(fs.readFileSync("input.json","utf8"));
const answer=JSON.parse(fs.readFileSync("answer.json","utf8"));
const expected=input.quantity*input.unitPrice;
console.log(JSON.stringify({input,answer,expected,match:answer.total===expected}));
if(answer.total!==expected) process.exit(1);
'

